**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ifstream plik("szyfr.txt");
    string klucz;
    plik >> klucz;
    // Buduj tablice odwrotna
    char odwrotna[26];
    for (int i = 0; i < 26; i++) {
        odwrotna[klucz[i] - 'a'] = 'a' + i;
    }
    string s;
    string maxNapis;
    int maxLen = 0;
    while (plik >> s) {
        string wynik = "";
        for (char c : s) {
            wynik += odwrotna[c - 'a'];
        }
        cout << s << " -> " << wynik << endl;
        if ((int)wynik.length() > maxLen) {
            maxLen = wynik.length();
            maxNapis = wynik;
        }
    }
    cout << "Najdluzszy: " << maxNapis << " (" << maxLen << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Klucz definiuje szyfr podstawieniowy: a->klucz[0], b->klucz[1], ... Aby odszyfrowac, budujemy odwrotna tablice. Dla znaku zaszyfrowanego c, szukamy pozycji c w kluczu — ta pozycja daje oryginalny znak.

